const input = $input.first().json;
const body = (typeof input.body === 'object' && input.body !== null) ? input.body : input;

const dealerId = String(body.dealer_id || '').trim();
const dealerSlug = String(body.dealer_slug || '').trim();
if (!dealerId || !dealerSlug) throw new Error('Falta dealer_id o dealer_slug');

const mode = String(body.stock_mode || '').trim();
const csvFiles = Array.isArray(body.stock_csv_files) ? body.stock_csv_files : [];

return [{ json: {
  source: 'manual',
  dealerId, dealerSlug,
  dealerName: String(body.dealer_name || dealerSlug),
  email: String(body.dealer_email || '').trim(),
  mode,
  csvUrl: mode === 'csv' && csvFiles[0] ? String(csvFiles[0].url || '') : '',
  bulkFiles: Array.isArray(body.stock_bulk_files) ? body.stock_bulk_files : [],
  notes: String(body.stock_notes || ''),
} }];

const dealers = $('Consultar dealers con feed').all().map(i => i.json);
const featureRows = $input.all().map(i => i.json);
const elegiblePlans = new Set(featureRows.map(r => r.plans && r.plans.slug).filter(Boolean));

const out = [];
for (const d of dealers) {
  if (!d.feed_url) continue;
  if (!elegiblePlans.has(d.subscription_plan)) continue;
  out.push({ json: {
    source: 'feed_scheduled',
    dealerId: d.id, dealerSlug: d.slug, dealerName: d.name,
    mode: 'feed_url',
    csvUrl: d.feed_url,
    bulkFiles: [],
    notes: '',
    email: d.email || '',
  } });
}
return out.length ? out : [{ json: { skip: true } }];

const d = $input.first().json;
if (d.skip) return [{ json: { skip: true } }];
return [{ json: d }];

const meta = $('IF - Fotos sueltas').first().json;
const body = $input.first().json;
const csvText = typeof body === 'string' ? body : (body.data || JSON.stringify(body));
return [{ json: { ...meta, csvText } }];

function parseCSVLine(line) {
  const fields = []; let cur = ''; let inQ = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (ch === '"') { if (inQ && line[i + 1] === '"') { cur += '"'; i++; } else inQ = !inQ; }
    else if ((ch === ',' || ch === ';') && !inQ) { fields.push(cur.trim()); cur = ''; }
    else cur += ch;
  }
  fields.push(cur.trim());
  return fields;
}

const ALIAS = {
  tipo: 'vehicle_type', tipo_vehiculo: 'vehicle_type',
  marca: 'brand_name', modelo: 'model_name', version: 'version',
  ano: 'year', anio: 'year', year: 'year', 'año': 'year',
  km: 'mileage_km', kilometros: 'mileage_km', kilometraje: 'mileage_km',
  precio: 'price', price: 'price', precio_consultar: 'price_on_request',
  combustible: 'fuel_type', cambio: 'transmission', transmision: 'transmission',
  potencia_cv: 'power_hp', cv: 'power_hp', potencia: 'power_hp',
  carroceria: 'body_type', 'carrocería': 'body_type', body_type: 'body_type',
  color: 'color_exterior', color_exterior: 'color_exterior', color_interior: 'color_interior',
  descripcion: 'description', description: 'description',
  vin: 'vin', bastidor: 'vin',
};

const d = $input.first().json;
const csvText = d.csvText || '';
const clean = csvText.replace(/^\uFEFF/, '').trim();
const lines = clean.split('\n').map(l => l.replace(/\r$/, '')).filter(Boolean);
if (lines.length < 2) throw new Error('CSV vacío o sin filas de datos: ' + d.dealerName);

const rawHeaders = parseCSVLine(lines[0]).map(h => h.toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/\s+/g, '_').trim());

const required = ['marca', 'modelo'];
const requiredEn = ['brand', 'model'];
const hasYear = rawHeaders.includes('ano') || rawHeaders.includes('anio') || rawHeaders.includes('year') || rawHeaders.includes('año');
const okEs = required.every(h => rawHeaders.includes(h)) && hasYear;
const okEn = requiredEn.every(h => rawHeaders.includes(h)) && hasYear;
if (!okEs && !okEn) throw new Error('El CSV de ' + d.dealerName + ' no tiene las columnas mínimas (marca, modelo, año)');

const rows = lines.slice(1).map(line => {
  const vals = parseCSVLine(line);
  const raw = Object.fromEntries(rawHeaders.map((h, i) => [h, vals[i] ?? '']));
  const row = {};
  for (const [k, v] of Object.entries(raw)) row[ALIAS[k] ?? k] = v;
  return row;
}).filter(r => r.brand_name && r.model_name);

if (!rows.length) throw new Error('El CSV de ' + d.dealerName + ' no tiene filas válidas (falta marca/modelo)');

const parsed = rows.map(r => ({
  vehicle_type: (r.vehicle_type || 'coche').toLowerCase().includes('moto') ? 'motorcycle' : 'car',
  brand_name: r.brand_name, model_name: r.model_name, version: r.version || undefined,
  year: r.year, mileage_km: r.mileage_km, price: r.price || undefined,
  price_on_request: /^(si|sí|yes|true|1)$/i.test(r.price_on_request || ''),
  fuel_type: r.fuel_type || undefined, transmission: r.transmission || undefined,
  power_hp: r.power_hp || undefined, color_exterior: r.color_exterior || undefined,
  color_interior: r.color_interior || undefined, body_type: r.body_type || undefined,
  description: (r.description || '').trim(), vin: r.vin || undefined,
}));

return [{ json: { ...d, rows: parsed } }];

const d = $input.first().json;
const rows = d.rows || [];
const needsAi = rows.map((r, i) => ({ i, r })).filter(x => (x.r.description || '').length < 40);

if (!needsAi.length) return [{ json: { ...d, aiSkipped: true } }];

const items = needsAi.map(x =>
  `[${x.i}] ${x.r.brand_name} ${x.r.model_name} ${x.r.version || ''} (${x.r.year || 's/año'}, ${x.r.mileage_km || 's/km'} km, ${x.r.price ? x.r.price + ' EUR' : 'precio a consultar'})`
).join('\n');

const briefing = `Eres redactor de fichas de vehículos premium para Black Label Market, marketplace de coches y motos de alta gama en España.
Para cada vehículo de la lista, escribe una descripción comercial de 2-3 frases en español, tono premium y directo, sin superlativos vacíos ni inventar datos no dados (nunca inventes estado, historial, extras o kilometraje real). Usa solo los datos que se dan.

Vehículos (formato [índice] marca modelo versión (año, km, precio)):
${items}

Devuelve SOLO un JSON válido: un array de objetos {"i": <índice>, "description": "<texto>"}, sin texto adicional.`;

return [{ json: { ...d, needsAiIndices: needsAi.map(x => x.i),
  openAIRequest: { model: $env.OPENAI_MODEL || 'gpt-4o-mini', max_tokens: 1500, messages: [{ role: 'user', content: briefing }] } } }];

const d = $('Preparar prompt IA descripciones').first().json;
if (d.aiSkipped) return [{ json: d }];

const ai = $input.first().json;
let text = '';
if (Array.isArray(ai.choices) && ai.choices[0]) text = ai.choices[0].message?.content || '';

let descriptions = [];
try {
  const match = text.match(/\[[\s\S]*\]/);
  descriptions = match ? JSON.parse(match[0]) : [];
} catch (e) { descriptions = []; }

const rows = d.rows.slice();
for (const item of descriptions) {
  if (rows[item.i] && item.description) rows[item.i] = { ...rows[item.i], description: item.description };
}

return [{ json: { ...d, rows } }];

const d = $input.first().json;
return [{ json: { dealerId: d.dealerId, dealerSlug: d.dealerSlug, dealerName: d.dealerName, email: d.email || '',
  source: d.source, rowCount: (d.rows || []).length,
  importBody: { dealer_slug: d.dealerSlug, rows: d.rows || [] } } }];

const d = $('Preparar import').first().json;
const raw = $input.first().json;

function extractJsonText(body) {
  if (typeof body === 'string') return body;
  if (body && typeof body === 'object') {
    if (typeof body.inserted !== 'undefined' || typeof body.error !== 'undefined') return null; // ya es el objeto real
    const buf = body._readableState && body._readableState.buffer;
    if (Array.isArray(buf) && buf.length) {
      const bytes = buf.map((b) => (b && b.data) ? b.data : []).flat();
      try { return Buffer.from(bytes).toString('utf8'); } catch (e) { return null; }
    }
  }
  return null;
}

let res = {};
if (raw.body && typeof raw.body === 'object' && (typeof raw.body.inserted !== 'undefined' || typeof raw.body.error !== 'undefined')) {
  res = raw.body;
} else {
  const text = extractJsonText(raw.body);
  try { res = text ? JSON.parse(text) : {}; } catch (e) { res = { error: 'Respuesta no parseable: ' + String(text).slice(0, 200) }; }
}

const inserted = Array.isArray(res.inserted) ? res.inserted.length : (res.inserted || 0);
const errors = Array.isArray(res.errors) ? res.errors : [];
const draftNoPhotos = Number(res.draftNoPhotos) || 0;
const statusCode = raw.statusCode;
const httpOk = statusCode >= 200 && statusCode < 300;
return [{ json: { ...d, ok: httpOk && !res.error, inserted, draftNoPhotos, errorCount: errors.length,
  errorSummary: errors.slice(0, 5).map(e => 'Fila ' + e.row + ': ' + e.message).join(' | '),
  apiError: res.error || (!httpOk ? ('HTTP ' + statusCode) : null) } }];

const d = $input.first().json;
return [{ json: { ...d,
  slackText: '*Stock importado (IA)*

*Showroom:* ' + d.dealerName + '
*Fuente:* ' + d.source + '
*Vehículos:* ' + d.inserted + (d.errorCount ? ' (' + d.errorCount + ' con error: ' + d.errorSummary + ')' : ''),
} }];

const d = $input.first().json;
return [{ json: { ...d,
  taskTitle: 'Fallo import stock IA - ' + d.dealerName,
  taskEvidence: 'Fuente: ' + d.source + '. ' + (d.apiError || d.errorSummary || 'Error desconocido') + '. ' + d.inserted + ' importados, ' + d.errorCount + ' con error.',
  slackText: '*Fallo al importar stock (IA)*\n\n*Showroom:* ' + d.dealerName + '\n*Fuente:* ' + d.source + '\n*Detalle:* ' + (d.apiError || d.errorSummary || 'ver Airtable'),
} }];

const d = $input.first().json;
const links = (d.bulkFiles || []).map(f => f.url).filter(Boolean).join('\n');
return [{ json: { ...d,
  taskTitle: 'Procesar fotos sueltas de stock - ' + d.dealerName,
  taskEvidence: 'Showroom envió fotos/archivos sueltos en la sala de configuración (no auto-importable sin datos estructurados). Notas: ' + (d.notes || '(sin notas)') + '. Archivos:\n' + (links || '(ninguno)'),
  slackText: '*Fotos sueltas pendientes de procesar*\n\n*Showroom:* ' + d.dealerName + '\n*Archivos:* ' + (d.bulkFiles || []).length + '\nRevisar tarea en Airtable para crear las fichas a mano.',
} }];

const d = $input.first().json;
const MARKET_URL = process.env.MARKET_URL || 'https://blacklabelmarket.es';
const MAIL_FROM = process.env.MAIL_FROM || 'Black Label Market <no-reply@blacklabelmarket.es>';
const n = d.draftNoPhotos;
const html = '<p>Hola,</p>' +
  '<p>Hemos importado el stock de <strong>' + d.dealerName + '</strong> correctamente, pero <strong>' + n + ' vehículo' + (n !== 1 ? 's' : '') + '</strong> ' + (n !== 1 ? 'no traían' : 'no traía') + ' fotos en el archivo.</p>' +
  '<p>' + (n !== 1 ? 'Esos vehículos se han' : 'Ese vehículo se ha') + ' guardado como borrador y <strong>no se publica' + (n !== 1 ? 'n' : '') + ' en el marketplace</strong> hasta que subas al menos una foto de cada uno.</p>' +
  '<p>Puedes hacerlo desde tu panel: <a href="' + MARKET_URL + '/dashboard/inventario">' + MARKET_URL + '/dashboard/inventario</a> — busca los vehículos marcados como "Borrador" y pulsa "Publicar".</p>' +
  '<p>El equipo de Black Label Market</p>';
return [{ json: { ...d,
  emailPayload: { from: MAIL_FROM, to: [d.email], subject: 'Acción requerida: fotos pendientes en tu stock importado', html },
  slackText: '*Fotos pendientes tras import de stock*\n\n*Showroom:* ' + d.dealerName + '\n*Vehículos en borrador sin foto:* ' + n + '\n*Aviso enviado a:* ' + d.email,
} }];
